var AMP_NAMES = ['lvl', 'pan', 'echo', 'void', 'cut'];

function makeGlue(SR) {
  // a simple feed-forward bus compressor (RMS detector, soft knee)
  var env = 0, gr = 1;
  var ka = 1 - Math.exp(-1 / (0.01 * SR)), kr = 1 - Math.exp(-1 / (0.18 * SR));
  return {
    amount: 0.2,
    tick: function (l, r) {
      var a = this.amount;
      var x = (l * l + r * r) * 0.5;
      env += (x - env) * (x > env ? ka : kr);
      var lvl = 10 * Math.log(env + 1e-12) / Math.LN10;          // dB
      var th = -12 - 14 * a, ratio = 1 + 5 * a;
      var over = lvl - th;
      var red = over > 0 ? over * (1 - 1 / ratio) : 0;
      var g = Math.pow(10, -red / 20) * (1 + a * 0.6);           // make-up
      gr = g;
      return g;
    },
    gr: function () { return gr; }
  };
}

class BunkerProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    var self = this, SR = sampleRate;
    this.SR = SR;
    this.drums = makeBunkerVoices(SR);
    this.echo = makeFx_echo(SR);
    this.void_ = makeFx_void(SR);
    this.fog = makeFx_fog(SR);
    this.dust = makeFx_dust(SR);
    this.glue = makeGlue(SR);
    this.comp = makeFx_comp(SR);
    this.sat = makeFx_sat(SR); this.satFocus = 0; this.swork = 0;
    this.cgr = 0; this.clvl = -100; this.swork = 0;
    this.echo.set('pmix', 1); this.echo.set('psend', 1);
    this.void_.set('pmix', 1);
    this.fog.set('pcut', 18000); this.fog.set('preso', 0.1); this.fog.set('pdrift', 0); this.fog.set('pmix', 1);
    this.dust.set('pcrackle', 0.2); this.dust.set('phiss', 0.15); this.dust.set('pwobble', 0.05); this.dust.set('pwear', 0.1); this.dust.set('pdrive', 0.2); this.dust.set('pfollow', 0.6);
    this.ret = { echo: 0.8, void: 0.7, master: 1.0, echo2void: 0.3 };
    this.on = { fog: 1, dust: 1, comp: 1, sat: 1 };
    this.ev = { trigs: [], play: {}, dump: null, base: [] };
    this.dirty = false;
    this.seq = make_bunker(function (o) {
      var a = Array.prototype.slice.call(arguments, 1);
      if (o === 0) { self.drums.set('v' + a[1] + 'trig', a[2]); self.ev.trigs.push([a[1], a[2] % 256]); }
      else if (o === 1) self.drums.set(a[2] < 8 ? 'v' + a[1] + 'p' + a[2] : 'v' + a[1] + AMP_NAMES[a[2] - 8], a[3]);
      else if (o === 2) self.ev.play[a[1]] = a[2];
      else if (o === 3) { if (a[0] === 'changed') self.dirty = true; else if (a[0] === 'dump') self.ev.dump = a[1]; }
      else if (o === 4) self.ev.base.push([a[1], a[2], a[3]]);
    }, ['bunker.js']);
    this.bpm = 126; this.playing = false; this.tick = 0; this.lastGrid = -1;
    this.seq.res(480); this.seq.tempo(this.bpm); this.echo.set('ptempo', this.bpm); this.drums.set('ptempo', this.bpm);
    this.peak = 0; this.flushIn = 0;
    this.lv = { echo: 0, void: 0 }; this.fogcut = 18000; this.pump = 1;
    this.port.onmessage = function (e) { self.message(e.data); };
    this.dirty = true;
  }
  message(m) {
    var s = this.seq;
    if (m.t === 'play') { this.playing = true; this.tick = 0; this.lastGrid = -1; }
    else if (m.t === 'stop') { this.playing = false; s.state(0); }
    else if (m.t === 'bpm') { this.bpm = Math.max(60, Math.min(200, m.v)); s.tempo(this.bpm); this.echo.set('ptempo', this.bpm); this.drums.set('ptempo', this.bpm); this.comp.set('ptempo', this.bpm); }
    else if (m.t === 'rum') this.drums.set(m.p, m.v);
    else if (m.t === 'seq') { var f = s[m.fn]; if (f) { f.apply(null, m.args); } }
    else if (m.t === 'fx') { var fx = { echo: this.echo, void: this.void_, fog: this.fog, dust: this.dust, comp: this.comp, sat: this.sat }[m.fx]; fx.set(m.p, m.v); }
    else if (m.t === 'ret') this.ret[m.k] = m.v;
    else if (m.t === 'glue') this.glue.amount = m.v;
    else if (m.t === 'on') this.on[m.k] = m.v ? 1 : 0;
    else if (m.t === 'satfocus') this.satFocus = m.v | 0;
    else if (m.t === 'audition') {
      // tapping a track pad plays it (counts down from the top, apart from the sequencer's counter)
      this.aud = ((this.aud || 0) + 1) % 100000;
      this.drums.set('v' + m.track + 'trig', (310000 + this.aud) * 256 + 110);
    }
  }
  process(inputs, outputs) {
    var out = outputs[0], L = out[0], R = out[1] || out[0], n = L.length;
    var SR = this.SR, d = this.drums, ret = this.ret;
    var tickInc = this.bpm / 60 * 480 / SR;
    var eL = 0, vL = 0;
    for (var i = 0; i < n; i++) {
      if (this.playing) {
        var g = Math.floor(this.tick / 10) * 10;
        if (g !== this.lastGrid) { this.lastGrid = g; this.seq.ticks(g); }
        this.tick += tickInc;
      }
      var o = d.tick();
      var dl = o[0], dr = o[1];
      if (this.on.sat) {
        // DRIVE before the compressor: the whole kit, the kick (+ rumble) only, or all but the kick
        var f = this.satFocus, kl = o[6], kr = o[7], s;
        if (f === 0) { s = this.sat.tick(dl, dr, 0, 0); dl = s[0]; dr = s[1]; }
        else if (f === 1) { s = this.sat.tick(kl, kr, 0, 0); dl = dl - kl + s[0]; dr = dr - kr + s[1]; }
        else { s = this.sat.tick(dl - kl, dr - kr, 0, 0); dl = kl + s[0]; dr = kr + s[1]; }
        if (s[2] > this.swork) this.swork = s[2];
      }
      if (this.on.comp) {
        // DRUM COMP on the dry drum bus (the sends to echo and void stay uncompressed)
        var c = this.comp.tick(dl, dr, 0, 0);
        dl = c[0]; dr = c[1];
        if (c[2] > this.cgr) this.cgr = c[2];
        if (c[3] > this.clvl) this.clvl = c[3];
      }
      var e = this.echo.tick(o[2], o[3], 0, 0);
      var w = this.void_.tick(o[4] + e[0] * ret.echo2void, o[5] + e[1] * ret.echo2void, 0, 0);
      var ml = dl + e[0] * ret.echo + w[0] * ret.void;
      var mr = dr + e[1] * ret.echo + w[1] * ret.void;
      eL += e[0] * e[0]; vL += w[0] * w[0];
      var gg = this.glue.tick(ml, mr);
      ml *= gg; mr *= gg;
      if (this.on.fog) {
        var f = this.fog.tick(ml, mr, (this.tick / 480) % 1, 0);
        ml = f[0]; mr = f[1]; this.fogcut = f[2]; this.pump = f[3];
      }
      if (this.on.dust) { var u = this.dust.tick(ml, mr, 0, 0); ml = u[0]; mr = u[1]; }
      ml = Math.tanh(ml * ret.master); mr = Math.tanh(mr * ret.master);
      L[i] = ml; R[i] = mr;
      var a = ml < 0 ? -ml : ml; if (a > this.peak) this.peak = a;
    }
    this.lv.echo = Math.max(this.lv.echo * 0.85, Math.sqrt(eL / n));
    this.lv.void = Math.max(this.lv.void * 0.9, Math.sqrt(vL / n));
    this.flushIn -= n;
    if (this.flushIn <= 0) {
      this.flushIn = Math.floor(SR / 40);
      if (this.dirty) { this.dirty = false; this.seq.dump(); }
      this.port.postMessage({ trigs: this.ev.trigs, play: this.ev.play, dump: this.ev.dump, base: this.ev.base, peak: this.peak,
        echo: this.lv.echo, void: this.lv.void, fogcut: this.fogcut, pump: this.pump, gr: this.glue.gr(), cgr: this.cgr, clvl: this.clvl, swork: this.swork, beat: this.tick / 480, playing: this.playing });
      this.ev = { trigs: [], play: {}, dump: null, base: [] };
      this.peak = 0; this.cgr = 0; this.clvl = -100; this.swork = 0;
    }
    return true;
  }
}
registerProcessor('bunker', BunkerProcessor);
